def fnv32(text):
    h = 2166136261
    for b in text.encode("utf-8"):
        h = ((h ^ b) * 16777619) & M32
    return h


def mix32(x):
    h = x & M32
    h ^= h >> 15
    h = (h * 0x2C1B3C6D) & M32
    h ^= h >> 12
    h = (h * 0x297A2D39) & M32
    h ^= h >> 15
    return h


def score(key, node):
    return mix32(fnv32(key) ^ mix32(fnv32(node)))


def place(key, nodes):
    best, best_score = None, -1
    for node in nodes:
        s = score(key, node)
        if s > best_score:
            best, best_score = node, s
    return best


def place_n(key, nodes, n):
    if n < 0:
        raise ValueError("n must not be negative")
    scores = [score(key, node) for node in nodes]
    order = sorted(range(len(nodes)), key=lambda i: (-scores[i], i))
    return [nodes[i] for i in order[:n]]


